// Floating-point end-to-end check. Only correctly rounded operations are used, so the
// riscv64 build under rvrun must print exactly what the native arm64 build prints
// (fp.expected, generated by build.sh). Inputs are volatile to stop constant folding.
#include <fenv.h>
#include <math.h>
#include <stdio.h>
#include <stdint.h>

static volatile double D[] = {1.0, -2.5, 3.0, 0.1, 1e308, 4.9e-324, -0.0, 1.0 / 3.0, 7.0};
static volatile float F[] = {1.0f, -2.5f, 3.0f, 0.1f, 3e38f, 1.4e-45f, -0.0f, 1.0f / 3.0f, 7.0f};
#define N 9

static const int modes[] = {FE_TONEAREST, FE_TOWARDZERO, FE_DOWNWARD, FE_UPWARD};
static const char *mode_names[] = {"rne", "rtz", "rdn", "rup"};

static void flags(void) {
    printf(" [%s%s%s%s%s]\n", fetestexcept(FE_INVALID) ? "NV" : "",
           fetestexcept(FE_DIVBYZERO) ? "DZ" : "", fetestexcept(FE_OVERFLOW) ? "OF" : "",
           fetestexcept(FE_UNDERFLOW) ? "UF" : "", fetestexcept(FE_INEXACT) ? "NX" : "");
    feclearexcept(FE_ALL_EXCEPT);
}

int main(void) {
    for (int m = 0; m < 4; m++) {
        fesetround(modes[m]);
        feclearexcept(FE_ALL_EXCEPT);
        printf("== %s\n", mode_names[m]);
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double a = D[i], b = D[j];
                printf("d %d %d: %a %a %a %a %a", i, j, a + b, a - b, a * b, a / b, fma(a, b, a));
                flags();
                float x = F[i], y = F[j];
                printf("s %d %d: %a %a %a %a %a", i, j, x + y, x - y, x * y, x / y, fmaf(x, y, x));
                flags();
            }
            double a = D[i];
            float x = F[i];
            printf("d %d: sqrt %a rint %a f %a l %ld u %lu", i, sqrt(a), rint(a), (float)a,
                   lrint(a * 1e3), (unsigned long)llrint(fabs(a) * 7));
            flags();
            printf("s %d: sqrt %a rint %a d %a l %ld", i, sqrtf(x), rintf(x), (double)x,
                   lrintf(x * 1e3f));
            flags();
        }
        volatile int64_t big = 0x7fffffffffffff01;
        volatile uint64_t ubig = 0xffffffffffffff01u;
        printf("cvt %a %a %a %a", (double)big, (float)big, (double)ubig, (float)ubig);
        flags();
    }
    fesetround(FE_TONEAREST);
    printf("nan %d %d %d inf %a min %a max %a\n", isnan(sqrt(D[1])), (int)(D[0] < NAN),
           (int)(NAN == NAN), D[4] * 10, fmin(D[1], NAN), fmax(NAN, D[2]));
    return 0;
}
